export type NbtAction = 
/**  List the rows again, chunks included (on mount or a search change). */
{ type: "refresh" } | { type: "toggle"; path: NbtStep[] } | { type: "expandAll"; path: NbtStep[] } | { type: "collapseAll" } | 
/**  Replace a value with typed text, read as the value's own type. */
{ type: "set"; path: NbtStep[]; text: string } | 
/**  Replace a value with SNBT of any type, e.g. a pasted compound. */
{ type: "setSnbt"; path: NbtStep[]; snbt: string } | { type: "rename"; path: NbtStep[]; name: string } | { type: "remove"; path: NbtStep[] } | 
/**  Add a new value inside `path` (a container) or after it. */
{ type: "add"; path: NbtStep[]; kind: number; name: string } | 
/**  Insert pasted SNBT inside or after `path`. */
{ type: "paste"; path: NbtStep[]; snbt: string; name: string } | { type: "undo" } | { type: "redo" };

export type NbtChunk = {
	index: number,
	x: number,
	z: number,
	timestamp: number,
	bytes: number,
	external: boolean,
};

export type NbtRow = {
	path: NbtStep[],
	depth: number,
	label: string,
	/**  The NBT type id (1 Byte … 12 Long array). */
	kind: number,
	preview: string,
	children: number,
	open: boolean,
	/**  Matched the search; ancestors of matches are listed with this false. */
	hit: boolean,
	/**  What an inline edit starts from, for values short enough to type. */
	text: string | null,
};

/**  One step into a container: a compound key (string) or a list index (number). */
export type NbtStep = number | string;

export type NbtView = {
	session: string,
	rows: NbtRow[],
	dirty: boolean,
	canUndo: boolean,
	canRedo: boolean,
	compression: string,
	isRegion: boolean,
	/**  Region coordinates from the file name, when it is a region file. */
	regionAt: [number, number] | null,
	/**  The chunk being edited, for region files. */
	chunk: number | null,
	/**  Sent only when the chunk list may have changed. */
	chunks: NbtChunk[] | null,
	/**  The row an action produced (a new value), to select and scroll to. */
	focus: NbtStep[] | null,
};

